mapper.select:
SELECT COUNT(*) FROM access_log
AND audit_action = #{auditAction}
AND username LIKE '%' || #{username} || '%' AND client_ip LIKE '%' || #{clientIp} || '%' AND response_status LIKE #{responseStatus} || '%' AND access_time >= CAST(#{startTime} AS timestamp) AND access_time <= CAST(#{endTime} AS timestamp)
